}

/* === Scrollbars === */
QScrollBar:vertical {
    background: #f5f6fa;
    width: 10px;
    border: none;
}

QScrollBar::handle:vertical {
    background: #bdc3c7;
    border-radius: 5px;
    min-height: 20px;
}

QScrollBar::handle:vertical:hover {
