}

/* === Wizard === */
QWizard {
    background: white;
}

QWizardPage {
    background: white;
}

/* === Dialog === */
QDialog {
    background: #f5f6fa;
}

from pathlib import Path

from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker

from src.utils.constants import DB_FILENAME


def get_db_path() -> Path:
    return Path(__file__).resolve().parent.parent.parent / DB_FILENAME


def create_db_engine(db_path: str | None = None):
    path = db_path or str(get_db_path())
    engine = create_engine(f"sqlite:///{path}", echo=False)
    return engine


def create_session_factory(engine):
    return sessionmaker(bind=engine)

from sqlalchemy.orm import DeclarativeBase


class Base(DeclarativeBase):
    pass

from sqlalchemy import select
from sqlalchemy.orm import Session

from src.database.models.godown import Godown


class GodownService:
    def __init__(self, session: Session):
        self.session = session

    def create_godown(self, code: str, name: str, address: str | None = None) -> Godown:
        godown = Godown(code=code, name=name, address=address)
        self.session.add(godown)
        self.session.commit()
        return godown

    def get_all_godowns(self) -> list[Godown]:
        return list(self.session.scalars(select(Godown).order_by(Godown.name)).all())

    def get_godown_by_id(self, godown_id: int) -> Godown | None:
        return self.session.get(Godown, godown_id)

    def delete_godown(self, godown_id: int) -> bool:
        godown = self.session.get(Godown, godown_id)
        if godown is None:
            return False
        try:
            self.session.delete(godown)
            self.session.commit()
            return True
        except Exception:
            self.session.rollback()
            raise

    def update_godown(self, godown_id: int, **kwargs) -> Godown | None:
        godown = self.session.get(Godown, godown_id)
        if godown is None:
            return None
        for key, value in kwargs.items():
            if hasattr(godown, key):
                setattr(godown, key, value)
        self.session.commit()
        return godown

from sqlalchemy import select
from sqlalchemy.orm import Session

from src.database.models.item import Item


class ItemService:
    def __init__(self, session: Session):
        self.session = session

    def _next_code(self) -> str:
        result = self.session.execute(
            select(Item.code).order_by(Item.code.desc())
        ).first()
        if result is None:
            return "ITM001"
        last_code = result[0]
        last_num = int(last_code[3:]) if last_code[3:].isdigit() else 0
        return f"ITM{last_num + 1:03d}"

    def create_item(
        self,
        name: str,
        unit: str,
        gst_rate: float = 0.0,
        hsn_code: str | None = None,
        opening_balance: float = 0.0,
    ) -> Item:
        code = self._next_code()
        item = Item(
            code=code,
            name=name,
            unit=unit,
            gst_rate=gst_rate,
            hsn_code=hsn_code,
            opening_balance=opening_balance,
        )
        self.session.add(item)
        self.session.commit()
        return item

    def get_all_items(self) -> list[Item]:
        return list(self.session.scalars(select(Item).order_by(Item.name)).all())

    def get_item_by_id(self, item_id: int) -> Item | None:
        return self.session.get(Item, item_id)

    def update_item(self, item_id: int, **kwargs) -> Item | None:
        item = self.session.get(Item, item_id)
        if item is None:
            return None
        for key, value in kwargs.items():
            setattr(item, key, value)
        self.session.commit()
        return item

    def delete_item(self, item_id: int) -> bool:
        item = self.session.get(Item, item_id)
        if item is None:
            return False
        try:
            self.session.delete(item)
            self.session.commit()
            return True
        except Exception:
            self.session.rollback()
            raise

from datetime import datetime

from sqlalchemy import func, select
from sqlalchemy.orm import Session

from src.database.models.invoice import SalesInvoice
from src.database.models.party import Party
from src.database.models.payment import PaymentTransaction
from src.database.models.purchase import PurchaseBill


class PaymentService:
    def __init__(self, session: Session):
        self.session = session

    def record_payment(
        self,
        payment_type: str,
        party_id: int,
        amount: float,
        payment_date: str | None = None,
        invoice_id: int | None = None,
        purchase_bill_id: int | None = None,
        mode: str = "cash",
        reference_no: str | None = None,
        notes: str | None = None,
    ) -> PaymentTransaction:
        if payment_date is None:
            payment_date = datetime.now().date().isoformat()
        txn = PaymentTransaction(
            payment_type=payment_type,
            party_id=party_id,
            invoice_id=invoice_id,
            purchase_bill_id=purchase_bill_id,
            payment_date=payment_date,
            amount=amount,
            mode=mode,
            reference_no=reference_no,
            notes=notes,
        )
        self.session.add(txn)
        self.session.commit()
        return txn

    def get_all_payments(self) -> list[PaymentTransaction]:
        return list(
            self.session.scalars(
                select(PaymentTransaction).order_by(PaymentTransaction.id.desc())
            ).all()
        )

    def get_payment_by_id(self, payment_id: int) -> PaymentTransaction | None:
        return self.session.get(PaymentTransaction, payment_id)

    def get_party_outstanding(self, party_id: int) -> float:
        total_billed = 0.0
        party = self.session.get(Party, party_id)
        if party is None:
            return 0.0

        if party.party_type in ("customer", "both"):
            result = self.session.execute(
                select(func.coalesce(func.sum(SalesInvoice.grand_total), 0)).where(
                    SalesInvoice.party_id == party_id,
                    SalesInvoice.status == "confirmed",
                )
            ).scalar()
            total_billed += result or 0.0

        if party.party_type in ("vendor", "both"):
            result = self.session.execute(
                select(func.coalesce(func.sum(PurchaseBill.grand_total), 0)).where(
                    PurchaseBill.party_id == party_id,
                    PurchaseBill.status == "confirmed",
                )
            ).scalar()
            total_billed += result or 0.0

        result = self.session.execute(
            select(func.coalesce(func.sum(PaymentTransaction.amount), 0)).where(
                PaymentTransaction.party_id == party_id
            )
        ).scalar()
        total_paid = result or 0.0

        return round(total_billed - total_paid, 2)

    def get_outstanding_invoices(self, party_id: int) -> list[dict]:
        party = self.session.get(Party, party_id)
        if party is None:
            return []
        results: list[dict] = []

        if party.party_type in ("customer", "both"):
            invoices = self.session.scalars(
                select(SalesInvoice).where(
                    SalesInvoice.party_id == party_id,
                    SalesInvoice.status == "confirmed",
                ).order_by(SalesInvoice.invoice_date)
            ).all()
            for inv in invoices:
                paid = self.session.execute(
                    select(func.coalesce(func.sum(PaymentTransaction.amount), 0)).where(
                        PaymentTransaction.invoice_id == inv.id
                    )
                ).scalar() or 0.0
                outstanding = round(inv.grand_total - paid, 2)
                if outstanding > 0:
                    results.append({
                        "type": "invoice",
                        "ref_id": inv.id,
                        "ref_no": inv.invoice_no,
                        "date": inv.invoice_date,
                        "total": inv.grand_total,
                        "paid": round(paid, 2),
                        "outstanding": outstanding,
                    })

        if party.party_type in ("vendor", "both"):
            bills = self.session.scalars(
                select(PurchaseBill).where(
                    PurchaseBill.party_id == party_id,
                    PurchaseBill.status == "confirmed",
                ).order_by(PurchaseBill.bill_date)
            ).all()
            for bill in bills:
                paid = self.session.execute(
                    select(func.coalesce(func.sum(PaymentTransaction.amount), 0)).where(
                        PaymentTransaction.purchase_bill_id == bill.id
                    )
                ).scalar() or 0.0
                outstanding = round(bill.grand_total - paid, 2)
                if outstanding > 0:
                    results.append({
                        "type": "purchase_bill",
                        "ref_id": bill.id,
                        "ref_no": bill.bill_no,
                        "date": bill.bill_date,
                        "total": bill.grand_total,
                        "paid": round(paid, 2),
                        "outstanding": outstanding,
                    })

        return results

from datetime import datetime

from sqlalchemy import func, select
from sqlalchemy.orm import Session

from src.database.models.invoice import SalesInvoice, SalesInvoiceItem
from src.database.models.item import Item
from src.database.models.party import Party
from src.database.models.payment import PaymentTransaction
from src.database.models.purchase import PurchaseBill
from src.database.models.stock import StockTransaction


class ReportService:
    def __init__(self, session: Session):
        self.session = session

    def stock_balance(self) -> list[dict]:
        rows = self.session.execute(
            select(
                Item.code, Item.name, Item.unit, Item.opening_balance,
                func.coalesce(func.sum(StockTransaction.quantity), 0).label("balance"),
            )
            .outerjoin(StockTransaction, Item.id == StockTransaction.item_id)
            .group_by(Item.id)
            .order_by(Item.name)
        ).all()
        return [
            {
                "code": r.code, "name": r.name, "unit": r.unit,
                "opening": r.opening_balance,
                "balance": float(r.balance),
            }
            for r in rows
        ]

    def stock_movement(self, item_id: int | None = None) -> list[dict]:
        query = (
            select(StockTransaction)
            .order_by(StockTransaction.transaction_date.desc(), StockTransaction.id.desc())
        )
        if item_id is not None:
            query = query.where(StockTransaction.item_id == item_id)
        txns = self.session.scalars(query).all()
        return [
            {
                "date": t.transaction_date,
                "type": t.transaction_type,
                "item": t.item.name if t.item else "",
                "godown": t.godown.name if t.godown else "",
                "qty": t.quantity,
                "rate": t.rate,
                "amount": t.amount,
                "party": t.party.name if t.party else "",
                "ref": f"{t.reference_type or ''} #{t.reference_id or ''}",
            }
            for t in txns
        ]

    def party_ledger(self, party_id: int, date_from: str | None = None, date_to: str | None = None) -> list[dict]:
        entries: list[dict] = []
        inv_q = select(SalesInvoice).where(
            SalesInvoice.party_id == party_id,
            SalesInvoice.status == "confirmed",
        )
        if date_from:
            inv_q = inv_q.where(SalesInvoice.invoice_date >= date_from)
        if date_to:
            inv_q = inv_q.where(SalesInvoice.invoice_date <= date_to)
        invoices = self.session.scalars(inv_q.order_by(SalesInvoice.invoice_date)).all()
        for inv in invoices:
            entries.append({
                "date": inv.invoice_date,
                "description": f"Sales Invoice {inv.invoice_no}",
                "debit": inv.grand_total,
                "credit": 0.0,
            })

        bill_q = select(PurchaseBill).where(
            PurchaseBill.party_id == party_id,
            PurchaseBill.status == "confirmed",
        )
        if date_from:
            bill_q = bill_q.where(PurchaseBill.bill_date >= date_from)
        if date_to:
            bill_q = bill_q.where(PurchaseBill.bill_date <= date_to)
        bills = self.session.scalars(bill_q.order_by(PurchaseBill.bill_date)).all()
        for b in bills:
            entries.append({
                "date": b.bill_date,
                "description": f"Purchase Bill {b.bill_no}",
                "debit": 0.0,
                "credit": b.grand_total,
            })

        pay_q = select(PaymentTransaction).where(
            PaymentTransaction.party_id == party_id,
        )
        if date_from:
            pay_q = pay_q.where(PaymentTransaction.payment_date >= date_from)
        if date_to:
            pay_q = pay_q.where(PaymentTransaction.payment_date <= date_to)
        payments = self.session.scalars(pay_q.order_by(PaymentTransaction.payment_date)).all()
        for p in payments:
            desc = f"Payment ({p.mode})"
            if p.reference_no:
                desc += f" - {p.reference_no}"
            if p.payment_type == "receipt":
                entries.append({
                    "date": p.payment_date,
                    "description": desc,
                    "debit": 0.0,
                    "credit": p.amount,
                })
            else:
                entries.append({
                    "date": p.payment_date,
                    "description": desc,
                    "debit": p.amount,
                    "credit": 0.0,
                })

        entries.sort(key=lambda e: e["date"])
        balance = 0.0
        for e in entries:
            balance += e["debit"] - e["credit"]
            e["balance"] = round(balance, 2)
        return entries

    def gst_summary(self, date_from: str | None = None, date_to: str | None = None) -> list[dict]:
        q = select(SalesInvoiceItem).join(SalesInvoice).where(
            SalesInvoice.status == "confirmed"
        )
        if date_from:
            q = q.where(SalesInvoice.invoice_date >= date_from)
        if date_to:
            q = q.where(SalesInvoice.invoice_date <= date_to)
        invoices = self.session.scalars(q).all()
        summary: dict[float, dict] = {}
        for item in invoices:
            rate = item.gst_rate
            if rate not in summary:
                summary[rate] = {"rate": rate, "taxable": 0, "cgst": 0, "sgst": 0, "igst": 0}
            summary[rate]["taxable"] += item.taxable
            summary[rate]["cgst"] += item.cgst
            summary[rate]["sgst"] += item.sgst
            summary[rate]["igst"] += item.igst
        return [
            {"rate": v["rate"], "taxable": round(v["taxable"], 2),
             "cgst": round(v["cgst"], 2), "sgst": round(v["sgst"], 2),
             "igst": round(v["igst"], 2)}
            for v in summary.values()
        ]

    def purchase_register(self, date_from: str | None = None, date_to: str | None = None) -> list[dict]:
        q = select(PurchaseBill).where(PurchaseBill.status == "confirmed")
        if date_from:
            q = q.where(PurchaseBill.bill_date >= date_from)
        if date_to:
            q = q.where(PurchaseBill.bill_date <= date_to)
        bills = self.session.scalars(q.order_by(PurchaseBill.bill_date.desc())).all()
        return [
            {
                "bill_no": b.bill_no, "date": b.bill_date,
                "party": b.party.name if b.party else "",
                "gross": b.gross_amount, "taxable": b.taxable_amount,
                "gst": b.cgst_total + b.sgst_total + b.igst_total,
                "grand": b.grand_total,
            }
            for b in bills
        ]

    def dashboard_summary(self) -> dict:
        today = datetime.now().date().isoformat()
        result = {
            "today_sales": 0.0,
            "total_receivables": 0.0,
            "total_payables": 0.0,
            "low_stock_items": [],
        }

        today_sales = self.session.execute(
            select(func.coalesce(func.sum(SalesInvoice.grand_total), 0)).where(
                SalesInvoice.invoice_date == today,
                SalesInvoice.status == "confirmed",
            )
        ).scalar()
        result["today_sales"] = round(today_sales or 0.0, 2)

        from src.services.payment_service import PaymentService
        ps = PaymentService(self.session)

        customers = self.session.scalars(
            select(Party).where(Party.party_type.in_(["customer", "both"]), Party.is_active)
        ).all()
        for c in customers:
            result["total_receivables"] += ps.get_party_outstanding(c.id)

        vendors = self.session.scalars(
            select(Party).where(Party.party_type.in_(["vendor", "both"]), Party.is_active)
        ).all()
        for v in vendors:
            result["total_payables"] += ps.get_party_outstanding(v.id)

        result["total_receivables"] = round(result["total_receivables"], 2)
        result["total_payables"] = round(result["total_payables"], 2)

        low_stock = self.session.execute(
            select(Item.code, Item.name, Item.unit,
                   func.coalesce(func.sum(StockTransaction.quantity), 0).label("balance"))
            .outerjoin(StockTransaction, Item.id == StockTransaction.item_id)
            .group_by(Item.id)
            .having(func.coalesce(func.sum(StockTransaction.quantity), 0) < 10)
            .order_by(Item.name)
        ).all()
        result["low_stock_items"] = [
            {"code": r.code, "name": r.name, "unit": r.unit, "balance": float(r.balance)}
            for r in low_stock
        ]
        return result

    def sales_register(self, date_from: str | None = None, date_to: str | None = None) -> list[dict]:
        q = select(SalesInvoice).where(SalesInvoice.status == "confirmed")
        if date_from:
            q = q.where(SalesInvoice.invoice_date >= date_from)
        if date_to:
            q = q.where(SalesInvoice.invoice_date <= date_to)
        invoices = self.session.scalars(q.order_by(SalesInvoice.invoice_date.desc())).all()
        return [
            {
                "invoice_no": inv.invoice_no, "date": inv.invoice_date,
                "party": inv.party.name if inv.party else "",
                "gross": inv.gross_amount, "taxable": inv.taxable_amount,
                "gst": inv.cgst_total + inv.sgst_total + inv.igst_total,
                "grand": inv.grand_total,
            }
            for inv in invoices
        ]

import hashlib

import bcrypt
from sqlalchemy import select
from sqlalchemy.orm import Session

from src.database.models.user import User


def _hash_password(password: str) -> str:
    return bcrypt.hashpw(password.encode(), bcrypt.gensalt()).decode()


def _check_password(password: str, password_hash: str) -> bool:
    try:
        return bcrypt.checkpw(password.encode(), password_hash.encode())
    except ValueError:
        return False


def _is_sha256_hash(h: str) -> bool:
    return len(h) == 64 and all(c in "0123456789abcdef" for c in h)


class UserService:
    def __init__(self, session: Session):
        self.session = session

    def authenticate(self, username: str, password: str) -> User | None:
        user = self.session.scalar(
            select(User).where(
                User.username == username,
                User.is_active,
            )
        )
        if user is None:
            return None
        if _check_password(password, user.password_hash):
            return user
        if _is_sha256_hash(user.password_hash) and user.password_hash == hashlib.sha256(password.encode()).hexdigest():
            user.password_hash = _hash_password(password)
            self.session.commit()
            return user
        return None

    def create_user(
        self,
        username: str,
        password: str,
        display_name: str,
        role: str,
    ) -> User:
        user = User(
            username=username,
            password_hash=_hash_password(password),
            display_name=display_name,
            role=role,
        )
        self.session.add(user)
        self.session.commit()
        return user

    def get_all_users(self) -> list[User]:
        return list(self.session.scalars(select(User).order_by(User.display_name)).all())

    def get_user_by_id(self, user_id: int) -> User | None:
        return self.session.get(User, user_id)

    def update_user(self, user_id: int, **kwargs) -> User | None:
        user = self.session.get(User, user_id)
        if user is None:
            return None
        if "password" in kwargs:
            kwargs["password_hash"] = _hash_password(kwargs.pop("password"))
        for key, value in kwargs.items():
            setattr(user, key, value)
        self.session.commit()
        return user

