from src.database.models.user import User from src.services.user_service import UserService from src.ui.helpers import make_header from src.utils.constants import UserRole
class UserDialog(QDialog): def __init__(self, service: UserService, user: User | None = None, parent=None): super().__init__(parent) self.service = service self.user = user self.setWindowTitle("Add User" if user is None else "Edit User") self.setMinimumWidth(400) self.setModal(True)
layout = QFormLayout(self) layout.setSpacing(8)
self.username_edit = QLineEdit() self.username_edit.setPlaceholderText("Username *") if user: self.username_edit.setText(user.username) self.username_edit.setEnabled(False) layout.addRow("Username *:", self.username_edit)
self.display_edit = QLineEdit() self.display_edit.setPlaceholderText("Display name *") if user: self.display_edit.setText(user.display_name) layout.addRow("Display Name *:", self.display_edit)
self.role_combo = QComboBox() for role in UserRole: self.role_combo.addItem(role.value.capitalize(), role.value) if user: self.role_combo.setCurrentIndex( self.role_combo.findData(user.role) ) layout.addRow("Role:", self.role_combo)
self.change_pwd_cb = QCheckBox("Change password") self.password_edit = QLineEdit() self.password_edit.setEchoMode(QLineEdit.EchoMode.Password) self.password_edit.setPlaceholderText("Min 4 characters") self.password_edit.setEnabled(False)
if user is None: self.password_edit.setEnabled(True) self.change_pwd_cb.setChecked(True) self.change_pwd_cb.hide() else: self.change_pwd_cb.toggled.connect(self.password_edit.setEnabled)
layout.addRow("", self.change_pwd_cb) layout.addRow("Password:", self.password_edit)
btn_layout = QHBoxLayout() save_btn = QPushButton("Save") cancel_btn = QPushButton("Cancel") btn_layout.addStretch() btn_layout.addWidget(save_btn) btn_layout.addWidget(cancel_btn) layout.addRow(btn_layout)
save_btn.clicked.connect(self._save) cancel_btn.clicked.connect(self.reject)
def _save(self): username = self.username_edit.text().strip() display_name = self.display_edit.text().strip() if not username: QMessageBox.warning(self, "Error", "Username is required.") return if not display_name: QMessageBox.warning(self, "Error", "Display name is required.") return role = self.role_combo.currentData() if self.user: kwargs = {"display_name": display_name, "role": role} if self.change_pwd_cb.isChecked(): pwd = self.password_edit.text() if len(pwd) < 4: QMessageBox.warning(self, "Error", "Password must be at least 4 characters.") return kwargs["password"] = pwd self.service.update_user(self.user.id, **kwargs) else: pwd = self.password_edit.text() if len(pwd) < 4: QMessageBox.warning(self, "Error", "Password must be at least 4 characters.") return self.service.create_user( username=username, password=pwd, display_name=display_name, role=role, ) self.accept()
