@Slot() def _add(self): session, svc = self._get_session_and_service() try: dialog = UserDialog(svc, parent=self) if dialog.exec(): self._load() finally: session.close()
@Slot() def _edit(self): row = self.table.currentRow() if row < 0: QMessageBox.information(self, "Select", "Please select a user to edit.") return user_id = self.table.item(row, 0).data(Qt.ItemDataRole.UserRole) session, svc = self._get_session_and_service() try: user = svc.get_user_by_id(user_id) if user is None: return dialog = UserDialog(svc, user, self) if dialog.exec(): self._load() finally: session.close()
@Slot() def _toggle_active(self): row = self.table.currentRow() if row < 0: QMessageBox.information(self, "Select", "Please select a user.") return user_id = self.table.item(row, 0).data(Qt.ItemDataRole.UserRole) session, svc = self._get_session_and_service() try: user = svc.get_user_by_id(user_id) if user is None: return new_state = not user.is_active svc.update_user(user.id, is_active=new_state) self._load() finally: session.close()

